def normalize_account_name(value):
    return "".join(ch for ch in str(value).lower() if ch.isalnum())

def account_password(app_name):
    target = normalize_account_name(app_name)
    exact = [entry for entry in account_passwords if normalize_account_name(entry["account_name"]) == target]
    candidates = exact or [
        entry for entry in account_passwords
        if target in normalize_account_name(entry["account_name"])
        or normalize_account_name(entry["account_name"]) in target
    ]
    if len(candidates) != 1:
        raise RuntimeError("Unable to resolve one account password for " + app_name)
    return candidates[0]["password"]

